// Generated by quail. Review and extend with edge cases.
import { test, expect } from '@playwright/test'

const BASE = process.env.BASE_URL ?? 'http://localhost:3000'

test.describe('Counter', () => {
  test.beforeEach(async ({ page }) => { await page.goto(BASE) })

  test('Counter: counter-root is visible', async ({ page }) => {
    await expect(page.getByTestId('counter-root').first()).toBeVisible()
  })

  test('Counter: counter-form is visible', async ({ page }) => {
    await expect(page.getByTestId('counter-form').first()).toBeVisible()
  })

  test('Counter: name-input is visible', async ({ page }) => {
    await expect(page.getByTestId('name-input').first()).toBeVisible()
  })

  test('Counter: submit is visible', async ({ page }) => {
    await expect(page.getByTestId('submit').first()).toBeVisible()
  })

  test('Counter: inc is visible', async ({ page }) => {
    await expect(page.getByTestId('inc').first()).toBeVisible()
  })

  test('Counter: counter-display is visible', async ({ page }) => {
    await expect(page.getByTestId('counter-display').first()).toBeVisible()
  })

  test('Counter: clicks input name-input', async ({ page }) => {
    const target = page.getByTestId('name-input').first()
    await target.click()
    await expect(target).toBeVisible()
  })

  test('Counter: click toggles aria-expanded on input', async ({ page }) => {
    const target = page.getByTestId('name-input').first()
    const before = await target.getAttribute('aria-expanded')
    await target.click()
    const after = await target.getAttribute('aria-expanded')
    expect(after).not.toBe(before)
  })

  test('Counter: fills the form and submits', async ({ page }) => {
    await page.getByTestId('name-input').first().fill('test')
    await page.getByTestId('submit').first().click()
    await expect(page.locator('text=/error|failed/i')).toHaveCount(0)
  })

  test('Counter: form blocks submit when required fields are empty', async ({ page }) => {
    await page.getByTestId('submit').first().click()
    // Required fields should still be visible — the form did not navigate.
    await expect(page.getByTestId('name-input').first()).toBeVisible()
    // And no success-shaped message should appear.
    await expect(page.locator('text=/success|welcome|signed in/i')).toHaveCount(0)
  })
})
